test('REQ-1-3-1: REQ-1-3-1 -the requested workflow UTF-8 CSV,the requested workflow', async ({ page }) => {
  const fileName = 'utf8-' + u() + '.csv';
  const workbookName = fileName.replace(/\.csv$/, '');
  const content = '名称,数量,备注\n苹果,3,"含,逗号"\nPen,2,English\n"含""引号""文本",,"第二行\n换行"\n';
  await importCsv(page, fileName, content);

  const grid = worksheetGrid(page);
  await expect(grid.getByRole('gridcell', { name: 'A1', exact: true })).toHaveText('名称');
  await expect(grid.getByRole('gridcell', { name: 'A2', exact: true })).toHaveText('苹果');
  await expect(grid.getByRole('gridcell', { name: 'B2', exact: true })).toHaveText('3');
  await expect(grid.getByRole('gridcell', { name: 'C2', exact: true })).toHaveText('含,逗号');
  await expect(grid.getByRole('gridcell', { name: 'A3', exact: true })).toHaveText('Pen');
  await expect(grid.getByRole('gridcell', { name: 'C3', exact: true })).toHaveText('English');
  await expect(grid.getByRole('gridcell', { name: 'A4', exact: true })).toHaveText('含"引号"文本');
  await expect(grid.getByRole('gridcell', { name: 'B4', exact: true })).toHaveText('');
  await expect(grid.getByRole('gridcell', { name: 'C4', exact: true })).toHaveText(/第二行[\s\S]*换行/);

  await page.reload();
  await expect(worksheetGrid(page).getByRole('gridcell', { name: 'A2', exact: true })).toHaveText('苹果');
  await page.goto('/');
  await expect(page.getByRole('link', { name: workbookName, exact: true })).toBeVisible();
});

test('REQ-3-1-1#3: REQ-3-1-1 -the requested workflow, the requested workflow, the requested workflow, the requested workflow', async ({ page }) => {
  await createBlankWorkbook(page);
  await setCellViaFormulaBar(page, 'A1', '2');
  await setCellViaFormulaBar(page, 'B1', '3');

  await cell(page, 'C1').click();
  await formulaBar(page).fill('=A1+B1');
  await cell(page, 'D1').click();
  await expect(cell(page, 'C1')).toHaveText('5');
  await cell(page, 'C1').click();
  await expect(formulaBar(page)).toHaveValue('=A1+B1');

  await cell(page, 'D1').click();
  await formulaBar(page).fill('=C1*2');
  await formulaBar(page).press('Enter');
  await expect(cell(page, 'D1')).toHaveText('10');

  await cell(page, 'A1').dblclick();
  const editA1 = page.getByRole('textbox', { name: 'Edit A1', exact: true });
  await editA1.fill('10');
  await editA1.press('Enter');
  await expect(cell(page, 'C1')).toHaveText('13');
  await expect(cell(page, 'D1')).toHaveText('26');

  await page.reload();
  await expect(cell(page, 'C1')).toHaveText('13');
  await expect(cell(page, 'D1')).toHaveText('26');
  await cell(page, 'C1').click();
  await expect(formulaBar(page)).toHaveValue('=A1+B1');
});

test('REQ-4-2-1#2: REQ-4-2-1 -the requested workflow', async ({ page }) => {
  await setupDependentState(page);

  await pasteExternal(page, 'A1', '5\t7\n6\t8');

  await expect(cell(page, 'A1')).toHaveText('5');
  await expect(cell(page, 'B1')).toHaveText('7');
  await expect(cell(page, 'C1')).toHaveText('12');
  await expect(cell(page, 'D1')).toHaveText('24');

  await selectCell(page, 'A1');
  await page.keyboard.press('Shift+ArrowRight');
  await page.keyboard.press('ControlOrMeta+x');
  await selectCell(page, 'F1');
  await page.keyboard.press('ControlOrMeta+v');

  await expect(cell(page, 'F1')).toHaveText('5');
  await expect(cell(page, 'G1')).toHaveText('7');
  await expect(cell(page, 'C1')).toHaveText('12');
  await expect(cell(page, 'D1')).toHaveText('24');
  await selectCell(page, 'C1');
  await expect(formulaBar(page)).toHaveValue('=F1+G1');

  await page.reload();
  await expect(grid(page)).toBeVisible();
  await expect(cell(page, 'C1')).toHaveText('12');
  await selectCell(page, 'C1');
  await expect(formulaBar(page)).toHaveValue('=F1+G1');
});

